import { randomUUID } from 'node:crypto';
import { appDb } from '../db';
import { recordEvent } from '../telemetry';

// While a conversation has an open support case, a person owns it: the assistant stays silent and
// the customer's messages wait for the operator. Closing the case hands the conversation back.
export function openCaseFor(conversationId: string) {
  return appDb()
    .prepare("SELECT id FROM incidents WHERE conversation_id=? AND status='open'")
    .get(conversationId) as { id: string } | undefined;
}

export function messageForSupport(
  userId: string,
  conversationId: string,
  incidentId: string,
  content: string,
) {
  const db = appDb(),
    runId = randomUUID(),
    messageId = randomUUID();
  db.transaction(() => {
    db.prepare('INSERT INTO messages VALUES(?,?,?,?,?,?)').run(
      messageId,
      conversationId,
      'user',
      content,
      new Date().toISOString(),
      null,
    );
    recordEvent(
      { userId, conversationId, runId, intentId: runId },
      'support.customer_message',
      { status: 'waiting_for_operator', incidentId, messageId },
    );
  })();
  return { handoff: true, incidentId, answer: null };
}

// Opening a conversation marks the operator's replies in it as seen.
export function markRead(conversationId: string) {
  appDb()
    .prepare(
      'INSERT INTO conversation_reads VALUES(?,?) ON CONFLICT(conversation_id) DO UPDATE SET read_at=excluded.read_at',
    )
    .run(conversationId, new Date().toISOString());
}

// The customer's conversation list, with whether support owns each one and how many operator
// replies the customer has not opened yet.
export function conversationsFor(userId: string) {
  return appDb()
    .prepare(
      `SELECT c.*,
        EXISTS(SELECT 1 FROM incidents i WHERE i.conversation_id=c.id AND i.status='open') AS with_support,
        (SELECT COUNT(*) FROM messages m WHERE m.conversation_id=c.id AND m.role='operator'
          AND m.created_at > COALESCE((SELECT read_at FROM conversation_reads r WHERE r.conversation_id=c.id), '')) AS unread
      FROM conversations c WHERE c.user_id=? ORDER BY c.created_at DESC`,
    )
    .all(userId);
}

